+        List<Integer> result = new ArrayList<>();
+        Queue<Integer> queue = new LinkedList<>();
+
+        for (int i = 0; i < graph.getVertexCount(); i++) {
+            if (!visited[i]) {
+                bfsFromVertex(graph, i, visited, result, queue);
+            }
+        }
+
